def render_local_game_payoff_audit(
    games: Sequence[Mapping[str, object]],
) -> str:
    """Render local-game payoff candidates as a self-contained HTML audit."""

    data = json.dumps(list(games), ensure_ascii=False, separators=(",", ":")).replace(
        "</", "<\\/"
    )
    return _HTML.replace("__DATA__", data)
